import Link from "next/link";
import type { Metadata } from "next";
import { Section, SectionTitle, PageHero } from "@/components/marketing/primitives";
import { FeatureCard, CtaBand } from "@/components/marketing/sections";
import { Reveal } from "@/components/marketing/Reveal";
import {
  IconShield,
  IconLock,
  IconServer,
  IconBackup,
  IconNetwork,
  IconCheck,
  IconScale,
  IconGauge,
} from "@/components/marketing/icons";

export const metadata: Metadata = {
  title: "Trust & Security — Nxeon",
  description:
    "How Nxeon keeps your servers and data safe: full KVM isolation, a host firewall that blocks VM-to-host traffic, edge DDoS mitigation, ZFS backups with one-click restore, 2FA, and no lock-in. An honest look at our real security posture.",
};

/** 1 — Tenant isolation: real hardware virtualization, no shared containers. */
const ISOLATION = [
  {
